/**
 * Marketing → Contacts tab — Iter 215bf (May 1, 2026).
 *
 * Purpose:
 *  Lite contact directory inside the Marketing Suite so customers on
 *  the Marketing-only license (£49/mo) can manage the contacts they've
 *  captured via lead-capture forms, edit details, import CSVs, and
 *  feed them into audiences and campaigns. Customers on the CRM
 *  license see the full pipeline + deals UI in the dedicated CRM app
 *  (`/crm`) — this tab is the marketing-only on-ramp.
 *
 *  Backend: `/api/marketing/contacts` (list/get/create/update/delete +
 *  bulk CSV import) gated by `require_module(("crm","marketing"))`.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { Search, Plus, Upload, Trash2, X, Loader2, AtSign, Phone as PhoneIcon, Tag, Sparkles } from 'lucide-react';
import CRMProTrialNudge from './CRMProTrialNudge';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { useAuth } from '@/App';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';

const PAGE_SIZE = 25;

export default function ContactsTab() {
  const { t } = useTranslation();
  const { token } = useAuth();
  const API = process.env.REACT_APP_BACKEND_URL;
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);

  const [search, setSearch] = useState('');
  const [contacts, setContacts] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [loading, setLoading] = useState(false);
  const [editing, setEditing] = useState(null); // contact | "new"

  const fileInputRef = useRef(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await axios.get(`${API}/api/marketing/contacts`, {
        headers,
        params: { search, skip: page * PAGE_SIZE, limit: PAGE_SIZE },
      });
      setContacts(data.contacts || []);
      setTotal(data.total || 0);
    } catch (e) {
      notifyApiError(notify, e, t('mkt.ct_load_err', 'Could not load contacts'));
    }
    setLoading(false);
  }, [API, headers, search, page]);

  useEffect(() => { load(); }, [load]);

  // Reset to page 0 when search changes (so users always see page 1 of new results).
  useEffect(() => { setPage(0); }, [search]);

  const handleDelete = async (c) => {
    if (!window.confirm(t('mkt.ct_delete_confirm', 'Delete {{email}}? This cannot be undone.', { email: c.email }))) return;
    try {
      await axios.delete(`${API}/api/marketing/contacts/${c.id}`, { headers });
      notify.success(t('mkt.ct_deleted', 'Contact deleted'));
      load();
    } catch (e) { notifyApiError(notify, e, t('mkt.ct_delete_err', 'Could not delete contact')); }
  };

  const handleImportClick = () => fileInputRef.current?.click();

  const handleImportFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = ''; // allow re-uploading same file
    const fd = new FormData();
    fd.append('file', file);
    try {
      const { data } = await axios.post(`${API}/api/marketing/contacts/import`, fd, {
        headers: { ...headers, 'Content-Type': 'multipart/form-data' },
      });
      notify.success(t('mkt.ct_import_done', 'Imported {{created}} new · {{updated}} updated · {{skipped}} skipped', { created: data.created, updated: data.updated, skipped: data.skipped }));
      load();
    } catch (e) { notifyApiError(notify, e, t('mkt.ct_import_err', 'CSV import failed')); }
  };

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  return (
    <div className="space-y-5" data-testid="marketing-contacts-tab">
      {/* Iter 215dl — CRM Lite is bundled with Marketing. Surfacing this
          framing turns "another tab in the email tool" into a perceived
          mini-CRM without spinning up a second app. Customers upgrade
          to CRM Pro when they need pipeline / deals / forecasting. */}
      <div
        className="rounded-xl border px-4 py-3 flex items-start gap-3"
        style={{ borderColor: 'var(--theme-border)', background: 'linear-gradient(135deg, rgb(217 70 239 / 0.06) 0%, rgb(99 102 241 / 0.06) 100%)' }}
        data-testid="crm-lite-badge"
      >
        <div className="h-8 w-8 rounded-lg flex items-center justify-center shrink-0" style={{ background: 'linear-gradient(135deg, #19cdff 0%, #19cdff 100%)', color: 'white' }}>
          <Sparkles size={14} />
        </div>
        <div className="min-w-0 text-sm">
          <p className="font-bold" style={{ color: 'var(--theme-text)' }}>
            <span className="inline-block px-1.5 py-0.5 rounded text-[10px] font-extrabold uppercase tracking-wider mr-1.5" style={{ background: '#6366f122', color: '#19cdff' }}>{t('mkt.ct_crm_lite', 'CRM Lite')}</span>
            {t('mkt.ct_included', 'included with Marketing')}
          </p>
          <p className="text-xs opacity-70 mt-0.5">
            {t('mkt.ct_lite_desc', 'Manage contacts, segments and lead-capture forms here. Need pipeline, deals or forecasting?')}{' '}
            <span className="font-semibold" style={{ color: 'var(--theme-text)' }}>{t('mkt.ct_upgrade', 'Upgrade to CRM Pro.')}</span>
          </p>
        </div>
      </div>

      {/* Iter 215dm — in-product upsell when the contact base scales
          past 250. Self-renders empty (returns null) if the tenant
          already has CRM Pro, dismissed, or below threshold. */}
      <CRMProTrialNudge totalContacts={total} threshold={250} />

      <div className="flex flex-wrap items-center gap-3">
        {/* search + actions row */}
        <div className="flex-1 min-w-[220px] relative">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search name, email, phone…"
            className="pl-9 h-10 rounded-xl bg-white border-slate-200 dark:bg-zinc-900 dark:border-zinc-800"
            data-testid="contacts-search"
          />
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv"
          onChange={handleImportFile}
          className="hidden"
          data-testid="contacts-import-input"
        />
        <Button
          variant="outline"
          onClick={handleImportClick}
          className="h-10 rounded-full border-slate-200 dark:border-zinc-800"
          data-testid="contacts-import-btn"
        >
          <Upload size={14} className="mr-1.5" /> {t('mkt.ct_import_csv', 'Import CSV')}
        </Button>
        <Button
          onClick={() => setEditing('new')}
          className="h-10 rounded-full bg-gradient-to-r from-[var(--gx-brand-from)] to-[var(--gx-brand-to)] text-white border-0 shadow-[0_6px_16px_-6px_rgba(25, 205, 255,0.35)]"
          data-testid="contacts-create-btn"
        >
          <Plus size={14} className="mr-1.5" /> {t('mkt.ct_new_contact', 'New contact')}
        </Button>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white overflow-hidden shadow-[0_1px_2px_rgba(27, 28, 29,0.04)] dark:bg-zinc-900 dark:border-zinc-800">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200 text-[11px] uppercase tracking-[0.16em] font-bold text-slate-500 dark:bg-zinc-900 dark:border-zinc-800">
              <th className="text-left px-5 py-3">{t('mkt.ct_th_name', 'Name')}</th>
              <th className="text-left px-5 py-3 hidden sm:table-cell">{t('mkt.ct_th_email', 'Email')}</th>
              <th className="text-left px-5 py-3 hidden md:table-cell">{t('mkt.ct_th_phone', 'Phone')}</th>
              <th className="text-left px-5 py-3 hidden lg:table-cell">{t('mkt.ct_th_tags', 'Tags')}</th>
              <th className="text-right px-5 py-3 w-1">{t('mkt.ct_th_actions', 'Actions')}</th>
            </tr>
          </thead>
          <tbody>
            {loading && (
              <tr><td colSpan={5} className="px-5 py-8 text-center text-slate-400"><Loader2 size={16} className="animate-spin inline mr-2" /> {t('mkt.ct_loading', 'Loading contacts…')}</td></tr>
            )}
            {!loading && contacts.length === 0 && (
              <tr><td colSpan={5} className="px-5 py-12 text-center">
                <div className="text-slate-700 font-semibold mb-1">{t('mkt.ct_empty_title', 'No contacts yet')}</div>
                <p className="text-sm text-slate-500 max-w-sm mx-auto">
                  {t('mkt.ct_empty_body', 'Capture leads with a Form on your site, import a CSV, or create one manually. Contacts feed Audiences, Campaigns and Journeys.')}
                </p>
              </td></tr>
            )}
            {!loading && contacts.map((c) => (
              <tr key={c.id} className="border-b border-slate-100 hover:bg-slate-50/50 dark:border-zinc-800" data-testid={`contact-row-${c.id}`}>
                <td className="px-5 py-3">
                  <button
                    type="button"
                    onClick={() => setEditing(c)}
                    className="font-semibold text-slate-900 hover:text-[var(--gx-brand-from)] text-left dark:text-zinc-100"
                  >
                    {(c.first_name || c.last_name) ? `${c.first_name || ''} ${c.last_name || ''}`.trim() : <span className="text-slate-400 italic">{t('mkt.ct_no_name', 'No name')}</span>}
                  </button>
                  <div className="text-xs text-slate-500 sm:hidden mt-0.5">{c.email}</div>
                </td>
                <td className="px-5 py-3 hidden sm:table-cell text-slate-700">{c.email}</td>
                <td className="px-5 py-3 hidden md:table-cell text-slate-500">{c.phone || '—'}</td>
                <td className="px-5 py-3 hidden lg:table-cell">
                  <div className="flex flex-wrap gap-1">
                    {(c.tags || []).slice(0, 3).map((tag) => (
                      <span key={tag} className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-slate-100 text-[11px] font-semibold text-slate-700 dark:bg-zinc-800"><Tag size={9} /> {tag}</span>
                    ))}
                  </div>
                </td>
                <td className="px-5 py-3 text-right">
                  <button
                    type="button"
                    onClick={() => handleDelete(c)}
                    className="text-slate-400 hover:text-red-600 p-1.5 rounded-lg hover:bg-red-50"
                    aria-label={t('mkt.ct_delete_aria', 'Delete contact')}
                    data-testid={`contact-delete-${c.id}`}
                  >
                    <Trash2 size={14} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-5 py-3 border-t border-slate-100 text-sm text-slate-600 dark:border-zinc-800">
            <span>{t('mkt.ct_pagination', 'Page {{page}} of {{total}} · {{count}} contacts', { page: page + 1, total: totalPages, count: total.toLocaleString() })}</span>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" disabled={page <= 0} onClick={() => setPage((p) => p - 1)} data-testid="contacts-prev">{t('mkt.ct_prev', 'Prev')}</Button>
              <Button variant="outline" size="sm" disabled={page + 1 >= totalPages} onClick={() => setPage((p) => p + 1)} data-testid="contacts-next">{t('mkt.ct_next', 'Next')}</Button>
            </div>
          </div>
        )}
      </div>

      {editing && (
        <ContactDialog
          contact={editing === 'new' ? null : editing}
          onClose={() => setEditing(null)}
          onSaved={() => { setEditing(null); load(); }}
          API={API}
          headers={headers}
        />
      )}
    </div>
  );
}

function ContactDialog({ contact, onClose, onSaved, API, headers }) {
  const { t } = useTranslation();
  const isNew = !contact;
  const [form, setForm] = useState({
    first_name: contact?.first_name || '',
    last_name: contact?.last_name || '',
    email: contact?.email || '',
    phone: contact?.phone || '',
    tags: (contact?.tags || []).join(', '),
    email_consent: contact?.marketing_consent?.email !== false,
    sms_consent: contact?.marketing_consent?.sms === true,
  });
  const [saving, setSaving] = useState(false);

  const save = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const body = {
        first_name: form.first_name.trim(),
        last_name: form.last_name.trim(),
        email: form.email.trim().toLowerCase(),
        phone: form.phone.trim() || null,
        tags: form.tags.split(',').map((tag) => tag.trim()).filter(Boolean),
        email_consent: form.email_consent,
        sms_consent: form.sms_consent,
      };
      if (isNew) {
        await axios.post(`${API}/api/marketing/contacts`, body, { headers });
        notify.success(t('mkt.ct_created', 'Contact created'));
      } else {
        await axios.put(`${API}/api/marketing/contacts/${contact.id}`, {
          ...body,
          marketing_consent: { email: body.email_consent, sms: body.sms_consent },
        }, { headers });
        notify.success(t('mkt.ct_updated', 'Contact updated'));
      }
      onSaved();
    } catch (e2) { notifyApiError(notify, e2, t('mkt.ct_save_err', 'Could not save contact')); }
    setSaving(false);
  };

  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="sm:max-w-md bg-white dark:bg-zinc-900">
        <DialogHeader>
          <DialogTitle>{isNew ? t('mkt.ct_new_contact', 'New contact') : t('mkt.ct_edit_contact', 'Edit contact')}</DialogTitle>
        </DialogHeader>
        <form onSubmit={save} className="space-y-3" data-testid="contact-dialog-form">
          <div className="grid grid-cols-2 gap-3">
            <Input value={form.first_name} onChange={(e) => setForm((f) => ({ ...f, first_name: e.target.value }))} placeholder={t('mkt.ct_first_name', 'First name')} data-testid="contact-first-name" />
            <Input value={form.last_name} onChange={(e) => setForm((f) => ({ ...f, last_name: e.target.value }))} placeholder={t('mkt.ct_last_name', 'Last name')} data-testid="contact-last-name" />
          </div>
          <div className="relative">
            <AtSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} placeholder="email@example.com" required type="email" className="pl-9" data-testid="contact-email" />
          </div>
          <div className="relative">
            <PhoneIcon size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} placeholder="Phone (optional)" className="pl-9" data-testid="contact-phone" />
          </div>
          <Input value={form.tags} onChange={(e) => setForm((f) => ({ ...f, tags: e.target.value }))} placeholder="Tags, comma separated" data-testid="contact-tags" />
          <div className="flex items-center gap-4 text-sm">
            <label className="inline-flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={form.email_consent} onChange={(e) => setForm((f) => ({ ...f, email_consent: e.target.checked }))} data-testid="contact-email-consent" />
              <span className="text-slate-700">Email consent</span>
            </label>
            <label className="inline-flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={form.sms_consent} onChange={(e) => setForm((f) => ({ ...f, sms_consent: e.target.checked }))} data-testid="contact-sms-consent" />
              <span className="text-slate-700">{t('mkt.ct_sms_consent', 'SMS consent')}</span>
            </label>
          </div>
          <DialogFooter className="pt-2">
            <Button type="button" variant="outline" onClick={onClose}><X size={14} className="mr-1.5" /> {t('mkt.ct_cancel', 'Cancel')}</Button>
            <Button type="submit" disabled={saving} className="bg-gradient-to-r from-[var(--gx-brand-from)] to-[var(--gx-brand-to)] text-white border-0" data-testid="contact-save-btn">
              {saving ? <><Loader2 size={14} className="animate-spin mr-1.5" /> {t('mkt.ct_saving', 'Saving…')}</> : t('mkt.ct_save_contact', 'Save contact')}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/* Dynamic Lists tab — auto-refreshing audience segments (Iter 229).
 *
 * Differs from static Audiences in two ways:
 *   • each list re-evaluates on read if older than its refresh interval
 *   • list rows show a "last refreshed" timestamp + manual refresh button
 *
 * Reuses the same FIELDS/OPS vocabulary as AudiencesTab so users learn
 * one rule-builder, not two.
 */
import React, { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { ListChecks, Plus, Sparkles, Loader2, Trash2, Save, RefreshCw, ChevronDown, ChevronUp, Clock } from 'lucide-react';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';

const BASE_FIELDS = [
  { id: 'lifetime_value_gbp', label: 'Lifetime value (£)', type: 'number' },
  { id: 'churn_risk_score', label: 'Churn risk score', type: 'number' },
  { id: 'attendance_30d', label: 'Visits in last 30 days', type: 'number' },
  { id: 'last_attended_at', label: 'Last attended', type: 'days_ago' },
  { id: 'signup_at', label: 'Signed up', type: 'days_ago' },
  { id: 'class_preference', label: 'Class preference', type: 'enum', options: ['spin', 'hiit', 'pt', 'yoga', 'strength'] },
  { id: 'subscription_tier', label: 'Subscription tier', type: 'enum', options: ['free', 'pro', 'premium'] },
  { id: 'payment_status', label: 'Payment status', type: 'enum', options: ['active', 'failed', 'cancelled'] },
];
const FIELD_TYPE_TO_RB = (ft) => {
  if (ft === 'number') return 'number';
  if (ft === 'date') return 'days_ago';
  if (ft === 'select' || ft === 'multi_select') return 'enum';
  return 'text';
};
const OPS = [
  { id: '>=', label: '≥' }, { id: '<=', label: '≤' }, { id: '==', label: '=' }, { id: '!=', label: '≠' },
];
const REFRESH_OPTIONS = [
  { value: 15, label: 'Every 15 minutes' },
  { value: 60, label: 'Hourly (default)' },
  { value: 240, label: 'Every 4 hours' },
  { value: 1440, label: 'Daily' },
];

const formatRelative = (iso) => {
  if (!iso) return 'never';
  const ms = Date.now() - new Date(iso).getTime();
  if (ms < 60_000) return 'just now';
  const m = Math.floor(ms / 60_000);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
};

const DynamicListsTab = ({ API, headers }) => {
  const { t } = useTranslation();
  const [lists, setLists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [draftName, setDraftName] = useState('');
  const [draftDescription, setDraftDescription] = useState('');
  const [draftInterval, setDraftInterval] = useState(60);
  const [draftConditions, setDraftConditions] = useState([]);
  const [draftPreviewSize, setDraftPreviewSize] = useState(0);
  const [busy, setBusy] = useState(false);
  const [expandedId, setExpandedId] = useState(null);
  const [members, setMembers] = useState({});
  const [customFields, setCustomFields] = useState([]);

  const FIELDS = React.useMemo(() => [...BASE_FIELDS, ...customFields], [customFields]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await axios.get(`${API}/api/marketing/dynamic-lists`, { headers });
      setLists(data.lists || []);
    } catch {
      notify.error(t('mkt.dl_load_err', 'Failed to load dynamic lists'));
    }
    setLoading(false);
  }, [API, headers]);

  const loadCustomProps = useCallback(async () => {
    try {
      const { data } = await axios.get(`${API}/api/custom-properties?entity_type=contact`, { headers });
      const cf = (data.properties || []).map((p) => ({
        id: `custom_fields.${p.key}`,
        label: `${p.label} (custom)`,
        type: FIELD_TYPE_TO_RB(p.field_type),
        options: (p.options || []).map((o) => o.value),
      }));
      setCustomFields(cf);
    } catch { /* noop */ }
  }, [API, headers]);

  useEffect(() => { load(); loadCustomProps(); }, [load, loadCustomProps]);

  const refreshDraftPreview = useCallback(async (conditions) => {
    try {
      const { data } = await axios.post(`${API}/api/marketing/audiences/preview`, {
        rules: { op: 'and', conditions },
      }, { headers });
      setDraftPreviewSize(data.estimated_size || 0);
    } catch { /* noop */ }
  }, [API, headers]);

  useEffect(() => {
    if (creating) refreshDraftPreview(draftConditions);
  }, [creating, draftConditions, refreshDraftPreview]);

  const addCondition = () => setDraftConditions((c) => [...c, { field: 'lifetime_value_gbp', op: '>=', value: 100 }]);
  const updateCondition = (i, patch) => setDraftConditions((c) => c.map((x, idx) => idx === i ? { ...x, ...patch } : x));
  const removeCondition = (i) => setDraftConditions((c) => c.filter((_, idx) => idx !== i));

  const save = async () => {
    if (!draftName.trim()) return;
    setBusy(true);
    try {
      await axios.post(`${API}/api/marketing/dynamic-lists`, {
        name: draftName,
        description: draftDescription,
        rules: { op: 'and', conditions: draftConditions },
        refresh_interval_minutes: draftInterval,
      }, { headers });
      notify.success(t('mkt.dl_created', 'Dynamic list created'));
      setDraftName(''); setDraftDescription(''); setDraftConditions([]); setDraftInterval(60);
      setCreating(false);
      load();
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dl_save_err', 'Save failed'));
    } finally { setBusy(false); }
  };

  const refreshOne = async (id) => {
    setBusy(true);
    try {
      await axios.post(`${API}/api/marketing/dynamic-lists/${id}/refresh`, {}, { headers });
      load();
      if (expandedId === id) loadMembers(id);
      notify.success(t('mkt.dl_refreshed', 'List refreshed'));
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dl_refresh_err', 'Refresh failed'));
    } finally { setBusy(false); }
  };

  const remove = async (id) => {
    if (!window.confirm(t('mkt.dl_delete_confirm', 'Delete this dynamic list?'))) return;
    try {
      await axios.delete(`${API}/api/marketing/dynamic-lists/${id}`, { headers });
      notify.success(t('mkt.dl_deleted', 'Deleted'));
      load();
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dl_delete_err', 'Delete failed'));
    }
  };

  const loadMembers = async (id) => {
    try {
      const { data } = await axios.get(`${API}/api/marketing/dynamic-lists/${id}/members?page=1&page_size=20`, { headers });
      setMembers((prev) => ({ ...prev, [id]: data.members || [] }));
    } catch { /* noop */ }
  };

  const toggleExpand = (id) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
      if (!members[id]) loadMembers(id);
    }
  };

  return (
    <div className="space-y-5" data-testid="marketing-dynamic-lists-tab">
      {/* Iter 216h245 — H2 "Dynamic Lists" removed (redundant with the
          tab pill). The "What is a Dynamic List?" explainer box stays —
          it's onboarding content, not a sub-header. */}
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div className="flex-1 min-w-0">
          <div className="max-w-3xl rounded-xl border border-fuchsia-200/60 bg-fuchsia-50/40 px-4 py-3 text-[13px] leading-relaxed" style={{ color: 'var(--theme-text)' }} data-testid="dynamic-lists-explainer">
            <strong className="text-fuchsia-700">{t('mkt.dl_explainer_title', 'What is a Dynamic List?')}</strong>
            <span className="text-[var(--theme-text-muted)]"> {t('mkt.dl_explainer_body', 'A saved audience that updates itself. You write a rule once (e.g. members joined in the last 30 days who skipped a class) and the list re-evaluates every time a contact\'s data changes — no manual refresh, no stale exports. Use them as campaign audiences or journey entry conditions. Compare with a Static list (fixed snapshot, never updates).')}</span>
          </div>
        </div>
        <button
          onClick={() => setCreating((c) => !c)}
          className="px-3 py-2 rounded-md bg-[var(--color-brand-blue)] text-white text-sm font-semibold inline-flex items-center gap-1.5"
          data-testid="dynamic-list-new-btn"
        >
          <Plus size={13} /> {creating ? t('mkt.dl_cancel', 'Cancel') : t('mkt.dl_new', 'New dynamic list')}
        </button>
      </div>

      {/* Create form */}
      {creating && (
        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-5 space-y-3" data-testid="dynamic-list-builder">
          <input
            value={draftName}
            onChange={(e) => setDraftName(e.target.value)}
            placeholder={t('mkt.dl_name_placeholder', 'List name')}
            className="w-full px-3 py-2 border border-zinc-200 dark:border-zinc-800 rounded-md text-sm bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100"
            data-testid="dynamic-list-name-input"
          />
          <input
            value={draftDescription}
            onChange={(e) => setDraftDescription(e.target.value)}
            placeholder={t('mkt.dl_desc_placeholder', 'Optional description')}
            className="w-full px-3 py-2 border border-zinc-200 dark:border-zinc-800 rounded-md text-sm bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100"
            data-testid="dynamic-list-desc-input"
          />
          <div className="space-y-2">
            {draftConditions.map((c, i) => {
              const f = FIELDS.find((x) => x.id === c.field) || FIELDS[0];
              return (
                <div key={i} className="flex items-center gap-2" data-testid={`dynamic-list-condition-${i}`}>
                  <select value={c.field} onChange={(e) => updateCondition(i, { field: e.target.value })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100">
                    {FIELDS.map((fld) => <option key={fld.id} value={fld.id}>{fld.label}</option>)}
                  </select>
                  <select value={c.op} onChange={(e) => updateCondition(i, { op: e.target.value })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs w-16 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100">
                    {OPS.map((op) => <option key={op.id} value={op.id}>{op.label}</option>)}
                  </select>
                  {f.type === 'enum' ? (
                    <select value={c.value} onChange={(e) => updateCondition(i, { value: e.target.value })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100">
                      {f.options.map((o) => <option key={o} value={o}>{o}</option>)}
                    </select>
                  ) : f.type === 'days_ago' ? (
                    <input type="text" value={c.value} onChange={(e) => updateCondition(i, { value: e.target.value })} placeholder="30d_ago" className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100" />
                  ) : (
                    <input type="number" value={c.value} onChange={(e) => updateCondition(i, { value: parseFloat(e.target.value) || 0 })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100" />
                  )}
                  <button onClick={() => removeCondition(i)} className="p-1 text-zinc-400 dark:text-zinc-500 hover:text-red-500"><Trash2 size={13} /></button>
                </div>
              );
            })}
            <button onClick={addCondition} className="inline-flex items-center gap-1 text-xs text-[var(--color-brand-blue)] font-semibold mt-1" data-testid="dynamic-list-add-condition">
              <Plus size={12} /> {t('mkt.dl_add_condition', 'Add condition')}
            </button>
          </div>
          <div className="flex items-center justify-between flex-wrap gap-2 mt-3 pt-3 border-t border-zinc-200 dark:border-zinc-800">
            <label className="text-xs inline-flex items-center gap-1.5" style={{ color: 'var(--theme-text-muted)' }}>
              <Clock size={12} /> Refresh:
              <select
                value={draftInterval}
                onChange={(e) => setDraftInterval(parseInt(e.target.value, 10))}
                className="px-2 py-1 border border-zinc-200 dark:border-zinc-800 rounded text-xs bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100"
                data-testid="dynamic-list-interval"
              >
                {REFRESH_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </label>
            <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>
              <Sparkles size={12} className="inline text-amber-500 mr-1" />
              <span className="font-bold" style={{ color: 'var(--theme-text)' }}>{draftPreviewSize.toLocaleString()}</span> contacts will match
            </p>
            <button
              onClick={save}
              disabled={busy || !draftName.trim()}
              className="px-3 py-1.5 rounded-md bg-[var(--color-brand-blue)] text-white text-xs font-semibold disabled:opacity-50 inline-flex items-center gap-1"
              data-testid="dynamic-list-save"
            >
              {busy ? <Loader2 size={11} className="animate-spin" /> : <Save size={11} />} Save
            </button>
          </div>
        </div>
      )}

      {/* Lists */}
      {loading ? (
        <div className="text-center py-12">
          <Loader2 size={32} className="animate-spin text-[var(--color-brand-blue)] mx-auto" />
        </div>
      ) : lists.length === 0 ? (
        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-10 text-center" data-testid="dynamic-list-empty">
          <ListChecks size={36} className="mx-auto text-zinc-300 dark:text-zinc-600 mb-3" />
          <p className="text-sm font-medium" style={{ color: 'var(--theme-text)' }}>{t('mkt.dl_empty_title', 'No dynamic lists yet')}</p>
          <p className="text-xs mt-1" style={{ color: 'var(--theme-text-muted)' }}>{t('mkt.dl_empty_hint', 'Create one to auto-refresh a segment as your contacts change.')}</p>
        </div>
      ) : (
        <div className="space-y-2" data-testid="dynamic-list-rows">
          {lists.map((l) => {
            const expanded = expandedId === l.id;
            return (
              <div key={l.id} className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900" data-testid={`dynamic-list-row-${l.id}`}>
                <div className="p-4 flex items-center gap-3 flex-wrap">
                  <button onClick={() => toggleExpand(l.id)} className="text-zinc-500 dark:text-zinc-400 hover:text-zinc-800 dark:hover:text-zinc-200" aria-label="Toggle">
                    {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                  </button>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-zinc-900 dark:text-zinc-100 truncate">{l.name}</p>
                    {l.description && (
                      <p className="text-[11px] text-zinc-500 dark:text-zinc-400 truncate">{l.description}</p>
                    )}
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold tabular-nums text-zinc-900 dark:text-zinc-100" data-testid={`dynamic-list-count-${l.id}`}>{(l.member_count || 0).toLocaleString()}</p>
                    <p className="text-[10px] text-zinc-400 dark:text-zinc-500">{t('mkt.dl_contacts', 'contacts')}</p>
                  </div>
                  <div className="text-right text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>
                    {t('mkt.dl_refreshed_rel', 'Refreshed {{rel}}', { rel: formatRelative(l.last_evaluated_at) })}<br />
                    {t('mkt.dl_every', 'every {{n}}m', { n: l.refresh_interval_minutes })}
                  </div>
                  <button
                    onClick={() => refreshOne(l.id)}
                    disabled={busy}
                    className="p-2 rounded hover:bg-zinc-100 dark:bg-zinc-800 dark:hover:bg-zinc-800 text-zinc-500 dark:text-zinc-400"
                    data-testid={`dynamic-list-refresh-${l.id}`}
                    title="Refresh now"
                  >
                    <RefreshCw size={13} />
                  </button>
                  <button
                    onClick={() => remove(l.id)}
                    className="p-2 rounded hover:bg-rose-50 dark:hover:bg-rose-950/40 text-rose-500"
                    data-testid={`dynamic-list-delete-${l.id}`}
                    title="Delete"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
                {expanded && (
                  <div className="border-t border-zinc-200 dark:border-zinc-800 p-4 bg-zinc-50/50 dark:bg-zinc-950/40" data-testid={`dynamic-list-members-${l.id}`}>
                    <p className="text-[10px] uppercase tracking-wider font-semibold mb-2" style={{ color: 'var(--theme-text-muted)' }}>
                      {t('mkt.dl_first_of', 'First {{shown}} of {{total}} members', { shown: (members[l.id] || []).length, total: (l.member_count || 0).toLocaleString() })}
                    </p>
                    {(members[l.id] || []).length === 0 ? (
                      <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('mkt.dl_no_members', 'No members match this list yet.')}</p>
                    ) : (
                      <div className="space-y-1">
                        {(members[l.id] || []).map((m) => (
                          <div key={m.id} className="flex items-center justify-between text-xs py-1">
                            <span className="text-zinc-800 dark:text-zinc-200">{m.first_name} {m.last_name}</span>
                            <span className="text-zinc-500 dark:text-zinc-400">{m.email}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default DynamicListsTab;

/**
 * EmailVolumePanel — customer-facing Email Volume + Bolt-on dialog.
 *
 * Shows the operator their current monthly email cap (base + active
 * bolt-on packs), this period's usage, and the catalog of packs they can
 * add. The end-to-end self-serve attach flow ships in a follow-up; for
 * now packs are attached by master admin so this dialog explains how to
 * request one.
 */
import { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { Mail, Plus, Sparkles } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { notify } from '@/components/notifications';

const fmtMoney = (pence, ccy = 'GBP') => {
  const sym = ccy === 'GBP' ? '£' : ccy === 'EUR' ? '€' : '$';
  return `${sym}${(Number(pence || 0) / 100).toFixed(2)}`;
};

const EmailVolumePanel = ({ API, headers, onClose }) => {
  const { t } = useTranslation();
  const [catalog, setCatalog] = useState({ rows: [], base: { included_emails: 5000 } });
  const [mine, setMine] = useState({ rows: [], limits: null, usage: { emails_sent: 0 } });
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [c, m] = await Promise.all([
        axios.get(`${API}/marketing/addons/catalog`, { headers: headers() }),
        axios.get(`${API}/marketing/addons/mine`, { headers: headers() }),
      ]);
      setCatalog(c.data || { rows: [] });
      setMine(m.data || { rows: [] });
    } catch (e) {
      notify.error(t('mkt.evp_load_err', 'Could not load email packs'), e.response?.data?.detail);
    }
    setLoading(false);
  }, [API, headers]);

  useEffect(() => { load(); }, [load]);

  const cap = mine.limits?.monthly_emails ?? catalog.base?.included_emails ?? 5000;
  const sent = mine.usage?.emails_sent ?? 0;
  const pct = cap > 0 ? Math.min(100, Math.round((sent / cap) * 100)) : 0;
  const attachedCodes = new Set((mine.rows || []).map((r) => r.code));

  const requestPack = (pack) => {
    const subject = `Pulse Fitness · request to enable ${pack.name}`;
    const body = `Hi Pulse Fitness team,\n\nPlease enable the "${pack.name}" pack on our Marketing module (+${pack.included_emails.toLocaleString()} emails / month at ${fmtMoney(pack.monthly_price_pence)}/mo).\n\nThanks!`;
    window.location.href = `mailto:hello@gymaxis.ai?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  };

  return (
    <Dialog open onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="max-w-2xl" data-testid="email-volume-panel">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Mail size={18} className="text-blue-600" />
            {t('mkt.evp_title', 'Email volume & bolt-on packs')}
          </DialogTitle>
        </DialogHeader>

        <div className="mb-5 mt-2 p-4 rounded-lg bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-blue-950/40 dark:to-indigo-950/40 border border-blue-100 dark:border-blue-900/60" data-testid="email-cap-summary">
          <div className="flex items-baseline gap-2 mb-2">
            <span className="text-2xl font-bold tabular-nums text-zinc-900 dark:text-zinc-100">{sent.toLocaleString()}</span>
            <span className="text-sm text-zinc-500">{t('mkt.evp_of_cap', '/ {{cap}} emails this period', { cap: cap.toLocaleString() })}</span>
          </div>
          <div className="h-2 rounded-full bg-zinc-200 overflow-hidden">
            <div
              className={`h-full transition-all ${pct >= 90 ? 'bg-rose-500' : pct >= 70 ? 'bg-amber-500' : 'bg-blue-600'}`}
              style={{ width: `${pct}%` }}
            />
          </div>
          <div className="mt-2 flex items-center justify-between text-[11px] text-zinc-500">
            <span>{t('mkt.evp_base_included', 'Base plan: {{n}} included', { n: (catalog.base?.included_emails ?? 5000).toLocaleString() })}</span>
            <span>{t('mkt.evp_from_packs', '+ {{emails}} from {{packs}} packs', { emails: ((mine.limits?.addon_emails) ?? 0).toLocaleString(), packs: (mine.rows || []).length })}</span>
          </div>
        </div>

        {(mine.rows || []).length > 0 && (
          <div className="mb-5">
            <h4 className="text-xs font-semibold uppercase tracking-wide text-zinc-500 mb-2">{t('mkt.evp_active_packs', 'Active bolt-on packs')}</h4>
            <div className="space-y-1.5">
              {mine.rows.map((p) => (
                <div key={p.id} className="flex items-center justify-between p-2.5 rounded border border-zinc-200 bg-white text-sm dark:bg-zinc-900 dark:border-zinc-800" data-testid={`active-pack-${p.code}`}>
                  <div>
                    <p className="font-semibold text-zinc-900 dark:text-zinc-100">{p.name}</p>
                    <p className="text-[11px] text-zinc-500">{t('mkt.evp_pack_line', '+{{emails}} emails / mo · {{price}}/mo', { emails: (p.included_emails || 0).toLocaleString(), price: fmtMoney(p.monthly_price_pence) })}</p>
                  </div>
                  <span className="px-2 py-0.5 rounded-full text-[10px] bg-emerald-100 text-emerald-700 font-semibold">{t('mkt.evp_active', 'Active')}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <h4 className="text-xs font-semibold uppercase tracking-wide text-zinc-500 mb-2 flex items-center gap-2">
          <Sparkles size={12} /> {t('mkt.evp_available_packs', 'Available packs')}
        </h4>
        {loading ? (
          <p className="text-sm text-zinc-400">{t('mkt.evp_loading', 'Loading…')}</p>
        ) : (catalog.rows || []).length === 0 ? (
          <p className="text-sm text-zinc-400">{t('mkt.evp_no_packs', 'No packs available right now.')}</p>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            {catalog.rows.map((pack) => {
              const active = attachedCodes.has(pack.code);
              return (
                <Card key={pack.code} className={`p-3 border ${active ? 'border-emerald-200 bg-emerald-50/50' : 'border-zinc-200'}`} data-testid={`pack-card-${pack.code}`}>
                  <div className="flex items-start justify-between mb-1.5">
                    <p className="font-semibold text-sm text-zinc-900 dark:text-zinc-100">{pack.name}</p>
                    <span className="text-sm font-bold text-zinc-900 dark:text-zinc-100">{fmtMoney(pack.monthly_price_pence)}<span className="text-[10px] text-zinc-400">/mo</span></span>
                  </div>
                  <p className="text-[11px] text-zinc-500 mb-2">
                    {pack.kind === 'sms'
                      ? t('mkt.evp_sms_line', '+{{n}} SMS / month', { n: (pack.included_sms || 0).toLocaleString() })
                      : t('mkt.evp_emails_line', '+{{n}} emails / month', { n: (pack.included_emails || 0).toLocaleString() })}
                  </p>
                  {active ? (
                    <Button size="sm" disabled className="w-full h-7 text-[11px] bg-emerald-100 text-emerald-700">{t('mkt.evp_already_active', 'Already active')}</Button>
                  ) : (
                    <Button size="sm" variant="outline" className="w-full h-7 text-[11px] border-blue-200 text-blue-700 hover:bg-blue-50" onClick={() => requestPack(pack)} data-testid={`pack-request-${pack.code}`}>
                      <Plus size={11} className="mr-1" /> {t('mkt.evp_request_enable', 'Request enable')}
                    </Button>
                  )}
                </Card>
              );
            })}
          </div>
        )}

        <p className="mt-4 text-[11px] text-zinc-400">
          Self-serve checkout for bolt-on packs ships in our next iteration. For now, tap "Request enable" — we'll add the pack to your account within one business day.
        </p>
      </DialogContent>
    </Dialog>
  );
};

export default EmailVolumePanel;

/**
 * EventsTab — Phase D (Iter 216ac)
 *
 * Event command-centre for studios:
 *   • Master event list (recitals, showcases, competitions, workshops, camps)
 *   • Per-event costume tracker (status, sizes, totals)
 *   • Rehearsal sub-schedule
 *   • AI-drafted parent comms (Claude Haiku) with one-click bulk announce
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import {
  Loader2, Plus, Trash2, Sparkles, Megaphone, Theater,
  CalendarRange, Users, X, Clock, MapPin, Wand2, ChevronRight,
} from 'lucide-react';
import { notify } from '@/components/notifications';
import { ModalShell, ModalActions, Input, Select } from '@/pages/Memberships/_shared';
import DatePicker from '@/components/shared/DatePicker';

const KIND_META = {
  recital:     { label: 'Recital',     emoji: 'R', tone: '#19cdff' },
  showcase:    { label: 'Showcase',    tone: '#19cdff' },
  competition: { label: 'Competition', tone: '#f59e0b' },
  workshop:    { label: 'Workshop',    tone: '#10b981' },
  camp:        { label: 'Camp',        tone: '#19cdff' },
  other:       { label: 'Event',       tone: '#6e7476' },
};

const COSTUME_TONES = {
  needed:   '#9a9fa1',
  ordered:  '#f59e0b',
  arrived:  '#19cdff',
  fitted:   '#10b981',
  paid:     '#16a34a',
  refunded: '#ef4444',
};
const COSTUME_NEXT = {
  needed: 'ordered', ordered: 'arrived', arrived: 'fitted', fitted: 'paid',
};

const fmtGBP = (p) => `£${(((p ?? 0) / 100) || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const fmtDT = (iso) => {
  if (!iso) return '—';
  try { return new Date(iso).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }); }
  catch { return iso.slice(0, 16); }
};

export default function EventsTab({ API, headers }) {
  const { t } = useTranslation();
  const auth = useMemo(() => ({ headers }), [headers]);
  const [loading, setLoading] = useState(true);
  const [events, setEvents] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  // Iter 216h250 — replaced the window.prompt() chain (which silently
  // cancelled the event when the user typed a kind that wasn't in
  // KIND_META) with a proper Pulse-themed modal that exposes the kind
  // values as a dropdown.
  const [createOpen, setCreateOpen] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/memberships/events`, auth);
      const rows = r.data?.events || [];
      setEvents(rows);
      if (!selectedId && rows.length) setSelectedId(rows[0].id);
    } catch (e) {
      notify.error(t('memberships_console.evt_load_fail', 'Failed to load events'), e?.response?.data?.detail || e.message);
    } finally { setLoading(false); }
  }, [API, auth, selectedId]);
  useEffect(() => { load(); }, [load]);

  const handleCreated = (id) => {
    setSelectedId(id);
    setCreateOpen(false);
    load();
  };

  const archiveEvent = async (event) => {
    if (!window.confirm(t('memberships_console.evt_archive_confirm', 'Archive "{{name}}"? Tickets and costumes are preserved.', { name: event.name }))) return;
    try {
      await axios.delete(`${API}/memberships/events/${event.id}`, auth);
      if (selectedId === event.id) setSelectedId(null);
      await load();
    } catch (e) {
      notify.error(t('memberships_console.evt_archive_fail', 'Archive failed'), e?.response?.data?.detail || e.message);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 text-sm text-muted-foreground p-6" data-testid="events-tab-loading">
        <Loader2 size={14} className="animate-spin" /> {t('memberships_console.evt_loading', 'Loading events…')}
      </div>
    );
  }

  const selected = events.find((e) => e.id === selectedId);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-[320px,1fr] gap-4" data-testid="events-tab">
      {/* Master list */}
      <aside className="rounded-2xl border p-3" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'var(--theme-surface, #fff)' }} data-testid="events-list-card">
        <header className="flex items-center justify-between mb-2">
          <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
            <Theater size={11} /> {t('memberships_console.evt_events', 'Events')}
          </p>
          <button type="button" onClick={() => setCreateOpen(true)} className="px-2 py-1 rounded text-[11px] font-bold inline-flex items-center gap-1" style={{ background: 'var(--color-brand-blue, #0091ca)', color: '#fff' }} data-testid="events-create">
            <Plus size={11} /> {t('memberships_console.evt_new', 'New')}
          </button>
        </header>
        {events.length === 0 ? (
          <div className="text-center py-8 px-3 rounded-xl border-2 border-dashed" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid="events-empty">
            <CalendarRange size={22} className="mx-auto mb-1 opacity-50" />
            <p className="text-sm font-bold">{t('memberships_console.evt_empty_title', 'No events yet')}</p>
            <p className="text-xs opacity-70 mt-1">{t('memberships_console.evt_empty_hint', 'Create your first recital or showcase to start tracking costumes & tickets.')}</p>
            <button
              type="button"
              onClick={() => setCreateOpen(true)}
              className="mt-3 inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-extrabold"
              style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-surface-darker)' }}
              data-testid="events-empty-create"
            >
              <Plus size={12} /> {t('memberships_console.evt_create_event', 'Create event')}
            </button>
          </div>
        ) : (
          <ul className="space-y-1.5" data-testid="events-list">
            {events.map((ev) => {
              const meta = KIND_META[ev.kind] || KIND_META.other;
              const active = ev.id === selectedId;
              return (
                <li key={ev.id}>
                  <button
                    type="button"
                    onClick={() => setSelectedId(ev.id)}
                    className={`w-full text-left rounded-lg p-2.5 border transition-all ${active ? 'ring-2' : ''}`}
                    style={{
                      borderColor: active ? meta.tone : 'var(--theme-border, #e0e0e0)',
                      background: active ? `${meta.tone}14` : 'transparent',
                      cursor: 'pointer', color: 'inherit',
                    }}
                    data-testid={`events-list-${ev.id}`}
                  >
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-bold uppercase px-1.5 py-0.5 rounded" style={{ background: meta.tone, color: '#fff' }}>
                        {t(`memberships_console.evt_kind_${ev.kind || 'other'}`, meta.label)}
                      </span>
                      <span className="text-[10px] opacity-60 tabular-nums ml-auto">{(ev.starts_at || '').slice(0, 10)}</span>
                    </div>
                    <p className="text-sm font-bold mt-1 truncate">{ev.name}</p>
                    <p className="text-[11px] opacity-70 truncate">{ev.venue || t('memberships_console.evt_venue_tbc', 'Venue TBC')}</p>
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </aside>

      {/* Detail */}
      {selected ? (
        <EventDetailCard
          API={API}
          auth={auth}
          event={selected}
          onChanged={load}
          onArchive={archiveEvent}
        />
      ) : (
        <div className="rounded-2xl border-2 border-dashed p-12 text-center" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid="events-detail-empty">
          <Theater size={28} className="mx-auto mb-2 opacity-50" />
          <p className="text-sm font-bold">{t('memberships_console.evt_select_prompt', 'Select or create an event to start')}</p>
        </div>
      )}
      {createOpen && (
        <CreateEventModal
          API={API}
          auth={auth}
          onClose={() => setCreateOpen(false)}
          onCreated={handleCreated}
        />
      )}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────
// Detail
// ─────────────────────────────────────────────────────────────────
function EventDetailCard({ API, auth, event, onChanged, onArchive }) {
  const { t } = useTranslation();
  const [rehearsals, setRehearsals] = useState([]);
  const [costumes, setCostumes] = useState([]);
  const [costumeSummary, setCostumeSummary] = useState({});
  const [loading, setLoading] = useState(true);
  const [aiOpen, setAiOpen] = useState(false);
  const [aiBusy, setAiBusy] = useState(false);
  const [draft, setDraft] = useState({ subject: '', body_html: '', audience: 'all_members' });
  const [announcing, setAnnouncing] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [r, c] = await Promise.all([
        axios.get(`${API}/memberships/events/${event.id}/rehearsals`, auth),
        axios.get(`${API}/memberships/events/${event.id}/costumes`, auth),
      ]);
      setRehearsals(r.data?.rehearsals || []);
      setCostumes(c.data?.costumes || []);
      setCostumeSummary(c.data?.summary || {});
    } finally { setLoading(false); }
  }, [API, auth, event.id]);
  useEffect(() => { load(); }, [load]);

  const meta = KIND_META[event.kind] || KIND_META.other;

  const addRehearsal = () => setRehearsalOpen(true);

  const removeRehearsal = async (r) => {
    if (!window.confirm(t('memberships_console.evt_remove_rehearsal', 'Remove "{{name}}"?', { name: r.name }))) return;
    await axios.delete(`${API}/memberships/events/${event.id}/rehearsals/${r.id}`, auth);
    load();
  };

  const addCostume = () => setCostumeOpen(true);

  const [rehearsalOpen, setRehearsalOpen] = useState(false);
  const [costumeOpen, setCostumeOpen] = useState(false);

  const advanceCostume = async (c) => {
    const next = COSTUME_NEXT[c.status];
    if (!next) return;
    try {
      await axios.patch(`${API}/memberships/events/${event.id}/costumes/${c.id}`, {
        status: next,
      }, auth);
      load();
    } catch (e) {
      notify.error(t('memberships_console.evt_update_fail', 'Update failed'), e?.response?.data?.detail || e.message);
    }
  };
  const removeCostume = async (c) => {
    if (!window.confirm(t('memberships_console.evt_remove_costume', 'Remove costume for {{name}}?', { name: c.attendee_name }))) return;
    await axios.delete(`${API}/memberships/events/${event.id}/costumes/${c.id}`, auth);
    load();
  };

  const draftWithAI = async () => {
    setAiBusy(true);
    setAiOpen(true);
    try {
      const r = await axios.post(`${API}/memberships/events/${event.id}/ai-comms`, {}, auth);
      setDraft({
        subject: r.data?.subject || t('memberships_console.evt_ai_subject_default', '{{name}} — important update', { name: event.name }),
        body_html: r.data?.body_html || '',
        audience: 'all_members',
      });
    } catch (e) {
      notify.error(t('memberships_console.evt_ai_fail', 'AI draft failed'), e?.response?.data?.detail || e.message);
    } finally { setAiBusy(false); }
  };

  const sendAnnouncement = async () => {
    if (!draft.subject.trim() || !draft.body_html.trim()) {
      notify.error(t('memberships_console.evt_need_subject_body', 'Need subject and body'));
      return;
    }
    setAnnouncing(true);
    try {
      const r = await axios.post(`${API}/memberships/events/${event.id}/announce`, draft, auth);
      notify.success(t('memberships_console.evt_announce_ok', 'Announcement sent'), t('memberships_console.evt_announce_stats', '{{sent}} of {{total}} delivered', { sent: r.data?.sent ?? 0, total: r.data?.audience_size ?? 0 }));
      setAiOpen(false);
      onChanged && onChanged();
    } catch (e) {
      notify.error(t('memberships_console.evt_send_fail', 'Send failed'), e?.response?.data?.detail || e.message);
    } finally { setAnnouncing(false); }
  };

  return (
    <section className="rounded-2xl border" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'var(--theme-surface, #fff)' }} data-testid="events-detail">
      <header className="p-4 border-b flex items-start gap-3 flex-wrap" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }}>
        <div className="rounded-full p-2.5" style={{ background: `${meta.tone}1f` }}>
          <Theater size={18} style={{ color: meta.tone }} />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-[11px] uppercase tracking-wider font-bold opacity-60">{t(`memberships_console.evt_kind_${event.kind || 'other'}`, meta.label)}</p>
          <h2 className="text-lg font-bold">{event.name}</h2>
          <div className="text-[12px] opacity-70 mt-1 flex flex-wrap items-center gap-2">
            <Clock size={11} /> {fmtDT(event.starts_at)} → {fmtDT(event.ends_at).split(', ').slice(-1)[0]}
            {event.venue ? (<><MapPin size={11} className="ml-2" /> {event.venue}</>) : null}
            {event.ticket_capacity > 0 ? (
              <><Users size={11} className="ml-2" /> {t('memberships_console.evt_tickets', '{{sold}}/{{cap}} tickets', { sold: event.tickets_sold ?? 0, cap: event.ticket_capacity })}</>
            ) : null}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button type="button" onClick={draftWithAI} className="px-3 py-1.5 rounded-lg text-xs font-bold inline-flex items-center gap-1.5" style={{ background: '#19cdff', color: '#fff' }} data-testid="events-ai-draft">
            <Sparkles size={11} /> {t('memberships_console.evt_ai_draft', 'AI draft comms')}
          </button>
          <button type="button" onClick={() => onArchive(event)} className="px-2 py-1 rounded text-[11px] border" style={{ borderColor: 'var(--theme-border)' }} data-testid="events-archive">
            <Trash2 size={11} />
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4">
        {/* Rehearsals */}
        <div className="rounded-xl border p-3" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid="events-rehearsals">
          <div className="flex items-center justify-between mb-2">
            <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
              <CalendarRange size={11} /> {t('memberships_console.evt_rehearsals', 'Rehearsals')}
            </p>
            <button type="button" onClick={addRehearsal} className="px-2 py-1 rounded text-[11px] font-bold inline-flex items-center gap-1" style={{ background: 'var(--color-brand-blue, #0091ca)', color: '#fff' }} data-testid="events-rehearsal-add">
              <Plus size={11} /> {t('memberships_console.evt_add', 'Add')}
            </button>
          </div>
          {loading ? <Loader2 size={14} className="animate-spin" /> : rehearsals.length === 0 ? (
            <p className="text-[11px] opacity-60 italic">{t('memberships_console.evt_no_rehearsals', 'No rehearsals scheduled — add one to keep parents informed.')}</p>
          ) : (
            <ul className="space-y-1.5" data-testid="events-rehearsal-list">
              {rehearsals.map((r) => (
                <li key={r.id} className="flex items-start gap-2 p-2 rounded border" style={{ borderColor: 'var(--theme-border)' }} data-testid={`events-rehearsal-${r.id}`}>
                  <Clock size={12} className="mt-0.5 opacity-60" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold truncate">{r.name}</p>
                    <p className="text-[11px] opacity-70 tabular-nums">{fmtDT(r.starts_at)}{r.room ? ` · ${r.room}` : ''}</p>
                  </div>
                  <button type="button" onClick={() => removeRehearsal(r)} className="opacity-60 hover:opacity-100" style={{ background: 'none', border: 0, cursor: 'pointer', color: 'inherit', padding: 0 }} data-testid={`events-rehearsal-remove-${r.id}`}>
                    <X size={12} />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>

        {/* Costumes */}
        <div className="rounded-xl border p-3" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid="events-costumes">
          <div className="flex items-center justify-between mb-2 gap-2 flex-wrap">
            <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
              <Users size={11} /> {t('memberships_console.evt_costumes', 'Costumes')}
              <span className="opacity-70 text-[10px] tabular-nums ml-1">
                {costumes.length} · {t('memberships_console.evt_total', '{{amount}} total', { amount: fmtGBP(costumeSummary.total_pence) })}
              </span>
            </p>
            <button type="button" onClick={addCostume} className="px-2 py-1 rounded text-[11px] font-bold inline-flex items-center gap-1" style={{ background: 'var(--color-brand-blue, #0091ca)', color: '#fff' }} data-testid="events-costume-add">
              <Plus size={11} /> {t('memberships_console.evt_add', 'Add')}
            </button>
          </div>
          {loading ? <Loader2 size={14} className="animate-spin" /> : costumes.length === 0 ? (
            <p className="text-[11px] opacity-60 italic">{t('memberships_console.evt_no_costumes', 'No costumes tracked yet — add one per student to keep on top of orders.')}</p>
          ) : (
            <ul className="space-y-1.5" data-testid="events-costume-list">
              {costumes.map((c) => {
                const tone = COSTUME_TONES[c.status] || '#9a9fa1';
                const next = COSTUME_NEXT[c.status];
                return (
                  <li key={c.id} className="flex items-start gap-2 p-2 rounded border" style={{ borderColor: 'var(--theme-border)' }} data-testid={`events-costume-${c.id}`}>
