              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold truncate">{p.name}</p>
                <p className="text-[11px] opacity-70 tabular-nums">
                  {fmtGBP(p.total_pence)} · {p.instalments} × {fmtGBP(p.instalment_pence)} ({p.frequency})
