export const CASE_TYPE_LABELS = {
  repair: 'Repair',
  ppm: 'PPM Service',
  install: 'Installation',
  inspection: 'Inspection',
  callout: 'Emergency callout',
  audit: 'Asset audit',
};

export function labelForCaseType(slug) {
