  const isHighPriority = priorityCode === 'P1' || priorityCode === 'P2';
  const caseTypeLabel = job?.case_type ? labelForCaseType(job.case_type) : null;
  const statusLabel = {
    new: t('service.eng_jd_status_new', 'New'),
