// ── Calibration capture — engineer records readings + pass/fail and
// generates an audit certificate (treadmill calibration etc.). Rows
// default from the PM service type's checklist items when present.
function CalibrationCapture({ job }) {
  const [rows, setRows] = useState([]);
  const [machines, setMachines] = useState(null); // null = flat mode; array = per-treadmill matrix
  const [serviceType, setServiceType] = useState('');
  const [overrideOverall, setOverrideOverall] = useState('');
  const [notes, setNotes] = useState('');
  const [sig, setSig] = useState('');
  const [showSig, setShowSig] = useState(false);
  const [busy, setBusy] = useState(false);
  const [saved, setSaved] = useState(false);
  const [open, setOpen] = useState(false);
  const [err, setErr] = useState('');

  useEffect(() => {
    (async () => {
      try {
        const { data } = await axios.get(`${API}/svc/engineer/jobs/${job.id}/calibration`, auth());
        setServiceType(data?.service_type || job.service_type || '');
        const treadmills = data?.treadmills || [];
        const params = data?.calibration_params || [];
        const existing = data?.calibration;
        if (treadmills.length && params.length) {
          // Per-treadmill matrix (Fire Station Service). Seed from saved data if present.
          const savedByKey = {};
          (existing?.machines || []).forEach((m) => { savedByKey[m.equipment_id || m.serial || m.equipment_name] = m; });
          const initial = treadmills.map((t) => {
            const key = t.equipment_id || t.serial || t.equipment_name;
            const sv = savedByKey[key];
            const readings = params.map((p) => {
              const svr = (sv?.readings || []).find((r) => r.label === p.label);
              return { label: p.label, target: p.target || '', unit: p.unit || '', measured: svr?.measured || '', result: svr?.result || 'pass' };
            });
            return {
              equipment_id: t.equipment_id, equipment_name: t.equipment_name, serial: t.serial || '',
              readings, overall_result: sv?.overall_result || 'pass',
            };
          });
          setMachines(initial);
          if (existing?.machines?.length) { setNotes(existing.notes || ''); setSaved(true); }
          setOpen(true);
          return;
        }
        // Flat mode (single-machine calibration).
        if (existing?.readings?.length) {
          setRows(existing.readings);
          setOverrideOverall(existing.overall_result || '');
          setNotes(existing.notes || '');
          setSaved(true); setOpen(true);
        } else {
          const defaults = data?.default_readings || [];
          if (defaults.length) {
            setRows(defaults.map((d) => ({ label: d.label, target: d.target || '', measured: '', unit: d.unit || '', tolerance: d.tolerance || '', result: 'pass' })));
            setOpen(true);
          } else {
            const labels = data?.checklist_items || [];
            setRows(labels.map((l) => ({ label: l, target: '', measured: '', unit: '', tolerance: '', result: 'pass' })));
            if (labels.length || /calibrat/i.test(data?.service_type || job.service_type || '')) setOpen(true);
          }
        }
      } catch { /* non-fatal */ }
    })();
  }, [job.id]);

  const matrixMode = Array.isArray(machines);
  const computedOverall = overrideOverall || (
    matrixMode
      ? (machines.some((m) => m.overall_result === 'fail') ? 'fail' : 'pass')
      : (rows.some((r) => r.result === 'fail') ? 'fail' : 'pass'));
  const setRow = (i, k, v) => setRows((p) => p.map((r, idx) => (idx === i ? { ...r, [k]: v } : r)));
  const addRow = () => setRows((p) => [...p, { label: '', target: '', measured: '', unit: '', tolerance: '', result: 'pass' }]);
  const rmRow = (i) => setRows((p) => p.filter((_, idx) => idx !== i));
  const setMachineReading = (mi, ri, v) => setMachines((p) => p.map((m, i) => (i === mi
    ? { ...m, readings: m.readings.map((r, j) => (j === ri ? { ...r, measured: v } : r)) } : m)));
  const setMachineResult = (mi, v) => setMachines((p) => p.map((m, i) => (i === mi
    ? { ...m, overall_result: v, readings: m.readings.map((r) => ({ ...r, result: v })) } : m)));

  const save = async () => {
    setBusy(true); setErr('');
    try {
      const body = matrixMode
        ? { machines, overall_result: computedOverall, notes, signature: sig, service_type: serviceType }
        : { readings: rows, overall_result: computedOverall, notes, signature: sig, service_type: serviceType, equipment_name: job.asset_name || '' };
      await axios.post(`${API}/svc/engineer/jobs/${job.id}/calibration`, body, auth());
      setSaved(true);
    } catch (e) {
      setErr(e?.response?.data?.detail || 'Could not save calibration');
    } finally { setBusy(false); }
  };

  const downloadCert = async () => {
    try {
      const r = await axios.get(`${API}/svc/engineer/jobs/${job.id}/calibration/certificate.pdf`,
        { ...auth(), responseType: 'blob' });
      const url = URL.createObjectURL(new Blob([r.data], { type: 'application/pdf' }));
      window.open(url, '_blank');
    } catch { setErr('Certificate not ready — save the calibration first.'); }
  };

  const inputCls = 'h-9 rounded-md border border-zinc-200 dark:border-zinc-700 bg-transparent px-2 text-xs';

  return (
    <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-4 mb-4" data-testid="calibration-capture">
      <button onClick={() => setOpen((o) => !o)} className="w-full flex items-center justify-between" data-testid="calibration-toggle">
        <span className="text-sm font-bold flex items-center gap-2">
          {matrixMode ? 'Treadmill calibration' : 'Calibration'}
          {matrixMode && <span className="text-[10px] px-2 py-0.5 rounded-full bg-blue-100 text-blue-700" data-testid="calibration-treadmill-count">{machines.length} treadmill{machines.length === 1 ? '' : 's'}</span>}
          {saved && (
            <span className={`text-[10px] px-2 py-0.5 rounded-full ${computedOverall === 'pass' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
              {computedOverall.toUpperCase()}
            </span>
          )}
        </span>
        <span className="text-xs text-zinc-400">{open ? 'Hide' : 'Show'}</span>
      </button>
      {open && matrixMode && (
        <div className="mt-3 space-y-3">
          <p className="text-[11px] text-zinc-500">Record speed &amp; incline readings for each treadmill. All treadmills appear on one certificate.</p>
          {machines.map((m, mi) => (
            <div key={m.equipment_id || mi} className="rounded-lg border border-zinc-200 dark:border-zinc-700 p-3" data-testid={`calibration-treadmill-${mi}`}>
              <div className="flex items-center justify-between mb-2">
                <div className="min-w-0">
                  <p className="text-xs font-bold truncate">{m.equipment_name}</p>
                  {m.serial && <p className="text-[10px] text-zinc-400 font-mono">SN {m.serial}</p>}
                </div>
                <select value={m.overall_result} onChange={(e) => setMachineResult(mi, e.target.value)} data-testid={`calibration-treadmill-result-${mi}`}
                  className={`${inputCls} px-1 ${m.overall_result === 'fail' ? 'text-rose-600 font-semibold' : 'text-emerald-600 font-semibold'}`}>
                  <option value="pass">Pass</option><option value="fail">Fail</option>
                </select>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                {m.readings.map((r, ri) => (
                  <label key={ri} className="text-[10px] text-zinc-500">
                    <span className="block mb-0.5 font-semibold">{r.label.replace('Speed — ', '').replace('Incline — ', '')}{r.label.startsWith('Speed') ? ' spd' : ' inc'}</span>
                    <input value={r.measured} onChange={(e) => setMachineReading(mi, ri, e.target.value)} placeholder={`${r.target}${r.unit ? ' ' + r.unit : ''}`}
                      className={`w-full ${inputCls}`} data-testid={`calibration-tm-${mi}-reading-${ri}`} />
                  </label>
                ))}
              </div>
            </div>
          ))}
          <textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Notes (reference instrument, observations)…" className="w-full rounded-md border border-zinc-200 dark:border-zinc-700 bg-transparent px-2 py-1.5 text-xs" rows={2} data-testid="calibration-notes" />
          <div>
            <button onClick={() => setShowSig((s) => !s)} className="text-xs font-semibold" data-testid="calibration-sign-toggle">
              {sig ? 'Signature captured ✓ — redo' : 'Add engineer signature'}
            </button>
            {showSig && (<div className="mt-2"><SignatureCanvas onCancel={() => setShowSig(false)} onSubmit={(d) => { setSig(d); setShowSig(false); }} /></div>)}
          </div>
          {err && <p className="text-xs text-rose-600" data-testid="calibration-error">{err}</p>}
          <div className="flex items-center gap-2 pt-1">
            <button onClick={save} disabled={busy} className="px-4 py-2 rounded-full text-sm font-semibold bg-[var(--color-brand-cyan)] text-[var(--color-ink)] disabled:opacity-50" data-testid="calibration-save">
              {busy ? 'Saving…' : (saved ? 'Update calibration' : 'Save calibration')}
            </button>
            {saved && (
              <button onClick={downloadCert} className="px-4 py-2 rounded-full text-sm font-semibold border border-zinc-300 dark:border-zinc-700" data-testid="calibration-download-cert">
                Download certificate
              </button>
            )}
          </div>
        </div>
      )}
      {open && !matrixMode && (
        <div className="mt-3 space-y-2">
          <div className="grid grid-cols-12 gap-1.5 text-[10px] font-semibold uppercase text-zinc-400 px-0.5">
            <span className="col-span-4">Parameter</span><span className="col-span-2">Target</span>
            <span className="col-span-2">Measured</span><span className="col-span-1">Unit</span>
            <span className="col-span-2">Result</span><span className="col-span-1" />
          </div>
          {rows.map((r, i) => (
            <div key={i} className="grid grid-cols-12 gap-1.5 items-center" data-testid={`calibration-row-${i}`}>
              <input value={r.label} onChange={(e) => setRow(i, 'label', e.target.value)} placeholder="Parameter" className={`col-span-4 ${inputCls}`} />
              <input value={r.target} onChange={(e) => setRow(i, 'target', e.target.value)} placeholder="Target" className={`col-span-2 ${inputCls}`} />
              <input value={r.measured} onChange={(e) => setRow(i, 'measured', e.target.value)} placeholder="Measured" className={`col-span-2 ${inputCls}`} data-testid={`calibration-measured-${i}`} />
              <input value={r.unit} onChange={(e) => setRow(i, 'unit', e.target.value)} placeholder="km/h" className={`col-span-1 ${inputCls} px-1`} />
              <select value={r.result} onChange={(e) => setRow(i, 'result', e.target.value)} data-testid={`calibration-result-${i}`} className={`col-span-2 ${inputCls} px-1`}>
                <option value="pass">Pass</option><option value="fail">Fail</option><option value="na">N/A</option>
              </select>
              <button onClick={() => rmRow(i)} className="col-span-1 text-zinc-400 text-xs" aria-label="Remove">✕</button>
            </div>
          ))}
          <button onClick={addRow} className="text-xs font-semibold text-[var(--color-brand-blue,#0091ca)]" data-testid="calibration-add">+ Add reading</button>
          <textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Notes (reference instrument, observations)…" className="w-full rounded-md border border-zinc-200 dark:border-zinc-700 bg-transparent px-2 py-1.5 text-xs" rows={2} data-testid="calibration-notes" />
          <div>
            <button onClick={() => setShowSig((s) => !s)} className="text-xs font-semibold" data-testid="calibration-sign-toggle">
              {sig ? 'Signature captured ✓ — redo' : 'Add engineer signature'}
            </button>
            {showSig && (
              <div className="mt-2">
                <SignatureCanvas onCancel={() => setShowSig(false)} onSubmit={(d) => { setSig(d); setShowSig(false); }} />
              </div>
            )}
          </div>
          {err && <p className="text-xs text-rose-600" data-testid="calibration-error">{err}</p>}
          <div className="flex items-center gap-2 pt-1">
            <button onClick={save} disabled={busy} className="px-4 py-2 rounded-full text-sm font-semibold bg-[var(--color-brand-cyan)] text-[var(--color-ink)] disabled:opacity-50" data-testid="calibration-save">
              {busy ? 'Saving…' : (saved ? 'Update calibration' : 'Save calibration')}
            </button>
            {saved && (
              <button onClick={downloadCert} className="px-4 py-2 rounded-full text-sm font-semibold border border-zinc-300 dark:border-zinc-700" data-testid="calibration-download-cert">
                Download certificate
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Service Ops · Engineers admin
 * ─────────────────────────────
 * Owner / Manager view to manage engineer profiles: create from existing
 * org users, edit skills / mobile / vehicle reg / working-hours / Sage
 * user id, and soft-deactivate. The data here drives the Phase 2 AI
 * auto-assign helper (skills + active flag).
 *
 * Iter 216v (Phase 3).
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { HardHat, Plus, Loader2, Trash2, Save, BadgeCheck, X, ExternalLink } from 'lucide-react';
import { toast } from 'sonner';
import ServiceOpsShell from './ServiceOpsShell';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const auth = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } });

const SKILL_OPTIONS = [
  'cardio', 'strength', 'electrical', 'mechanical', 'hydraulic',
  'plate-loaded', 'cable', 'install', 'commissioning',
];

const QUAL_SUGGESTIONS = [
  'IOSH Working Safely', 'PAT Tester', 'CSCS Card', 'NEBOSH',
  '18th Edition', 'First Aid at Work', 'Working at Height', 'Confined Spaces',
];

export default function EngineersAdminPage() {
  const { t } = useTranslation();
  const [engineers, setEngineers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [addBusy, setAddBusy] = useState(false);
  const [addForm, setAddForm] = useState({
    email: '', full_name: '', mobile: '', vehicle_reg: '', sage_user_id: '', skills: [],
    // Iter 216h87 — trust fields settable at creation
    photo_url: '', qualifications: [], years_experience: '', verified: false,
  });
  const [editingId, setEditingId] = useState(null);
  const [editDraft, setEditDraft] = useState({});
  // Iter 276b — cross-org machine-access requests from engineers.
  const [requests, setRequests] = useState([]);
  const [reqBusy, setReqBusy] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [engRes, reqRes] = await Promise.all([
        axios.get(`${API}/svc/engineers`, auth()),
        axios.get(`${API}/svc/access-requests?status=pending`, auth()).catch(() => ({ data: {} })),
      ]);
      setEngineers(engRes.data.engineers || []);
      setRequests(reqRes.data.requests || []);
    } catch {
      toast.error(t('service.eng_load_failed', 'Could not load engineers'));
    }
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const decideRequest = async (id, action) => {
    setReqBusy(id);
    try {
      await axios.post(`${API}/svc/access-requests/${id}/${action}`, {}, auth());
      toast.success(action === 'approve' ? t('service.eng_access_granted', 'Access granted') : t('service.eng_request_declined', 'Request declined'));
      await load();
    } catch (e) {
      toast.error(e?.response?.data?.detail || t('service.eng_request_update_failed', 'Could not update request'));
    } finally {
      setReqBusy('');
    }
  };

  const create = async () => {
    if (!addForm.email || !addForm.full_name) {
      toast.error(t('service.eng_email_name_required', 'Email and name are required'));
      return;
    }
    setAddBusy(true);
    try {
      const payload = { ...addForm };
      if (payload.years_experience === '' || payload.years_experience == null) {
        delete payload.years_experience;
      } else {
        payload.years_experience = Math.max(0, parseInt(payload.years_experience, 10) || 0);
      }
      await axios.post(`${API}/svc/engineers`, payload, auth());
      toast.success(t('service.eng_added', 'Engineer added'));
      setShowAdd(false);
      setAddForm({
        email: '', full_name: '', mobile: '', vehicle_reg: '', sage_user_id: '', skills: [],
        photo_url: '', qualifications: [], years_experience: '', verified: false,
      });
      await load();
    } catch (e) {
      toast.error(e.response?.data?.detail || t('service.eng_add_failed', 'Could not add engineer'));
    }
    setAddBusy(false);
  };

  const save = async (id) => {
    try {
      const payload = { ...editDraft };
      // Coerce years_experience to int / null
      if (payload.years_experience === '' || payload.years_experience == null) {
        payload.years_experience = null;
      } else {
        payload.years_experience = Math.max(0, parseInt(payload.years_experience, 10) || 0);
      }
      await axios.patch(`${API}/svc/engineers/${id}`, payload, auth());
      toast.success(t('service.eng_saved', 'Saved'));
      setEditingId(null);
      setEditDraft({});
      await load();
    } catch (e) {
      toast.error(e.response?.data?.detail || t('service.eng_save_failed', 'Save failed'));
    }
  };

  const deactivate = async (id) => {
    if (!window.confirm(t('service.eng_deactivate_confirm', 'Deactivate this engineer? They won’t receive new assignments.'))) return;
    try {
      await axios.delete(`${API}/svc/engineers/${id}`, auth());
      toast.success(t('service.eng_deactivated', 'Deactivated'));
      await load();
    } catch (e) {
      toast.error(e.response?.data?.detail || t('service.eng_failed', 'Failed'));
    }
  };

  const beginEdit = (eng) => {
    setEditingId(eng.id);
    setEditDraft({
      mobile: eng.mobile || '',
      vehicle_reg: eng.vehicle_reg || '',
      sage_user_id: eng.sage_user_id || '',
      skills: eng.skills || [],
      active: eng.active !== false,
      // Iter 216h87 — trust card fields
      photo_url: eng.photo_url || '',
      qualifications: eng.qualifications || [],
      years_experience: eng.years_experience || '',
      verified: !!eng.verified,
    });
  };

  const toggleQual = (qual, target = 'edit') => {
    if (target === 'add') {
      const cur = new Set(addForm.qualifications || []);
      if (cur.has(qual)) cur.delete(qual); else cur.add(qual);
      setAddForm({ ...addForm, qualifications: [...cur] });
    } else {
      const cur = new Set(editDraft.qualifications || []);
      if (cur.has(qual)) cur.delete(qual); else cur.add(qual);
      setEditDraft({ ...editDraft, qualifications: [...cur] });
    }
  };

  const addCustomQual = (raw, target = 'edit') => {
    const q = (raw || '').trim();
    if (!q) return;
    if (target === 'add') {
      const cur = new Set(addForm.qualifications || []);
      cur.add(q);
      setAddForm({ ...addForm, qualifications: [...cur] });
    } else {
      const cur = new Set(editDraft.qualifications || []);
      cur.add(q);
      setEditDraft({ ...editDraft, qualifications: [...cur] });
    }
  };

  // Iter 216h87 follow-up — Preview public tracking page for any engineer.
  const previewTracking = async (engineerId, engineerName) => {
    try {
      const r = await axios.get(`${API}/svc/engineers/${engineerId}/preview-tracking-link`, auth());
      const url = r.data?.url;
      if (!url) throw new Error('No URL returned');
      window.open(url, '_blank', 'noopener');
    } catch (e) {
      const msg = e?.response?.data?.detail || e.message;
      toast.error(t('service.eng_cannot_preview', 'Cannot preview {{name}}', { name: engineerName }), { description: msg });
    }
  };

  const toggleSkill = (skill, target) => {
    if (target === 'add') {
      const cur = new Set(addForm.skills);
      cur.has(skill) ? cur.delete(skill) : cur.add(skill);
      setAddForm({ ...addForm, skills: [...cur] });
    } else {
      const cur = new Set(editDraft.skills || []);
      cur.has(skill) ? cur.delete(skill) : cur.add(skill);
      setEditDraft({ ...editDraft, skills: [...cur] });
    }
  };

  const actions = useMemo(() => (
    <button
      type="button"
      onClick={() => setShowAdd((v) => !v)}
      className="svc-btn svc-btn-primary"
      data-testid="engineers-add-btn"
    >
      <Plus size={14} /> {t('service.eng_add', 'Add engineer')}
    </button>
  ), []);

  return (
    <ServiceOpsShell
      active="engineers"
      title={t('service.eng_title', 'Engineers')}
      subtitle={t('service.eng_subtitle', 'Profiles, skills, vehicles & Sage links — drives AI auto-assign.')}
      icon={HardHat}
      actions={actions}
    >
      {requests.length > 0 && (
        <section
          className="svc-card mb-3"
          style={{ padding: 16, border: '1px solid var(--theme-border)' }}
          data-testid="access-requests-panel"
        >
          <p className="text-[11px] font-bold uppercase tracking-wide" style={{ color: 'var(--theme-text-muted)', marginBottom: 10 }}>
            {t('service.eng_access_requests', 'Machine access requests ({{n}})', { n: requests.length })}
          </p>
          <div className="space-y-2">
            {requests.map((r) => (
              <div
                key={r.id}
                className="flex items-center justify-between gap-3 rounded-xl"
                style={{ padding: 10, border: '1px solid var(--theme-border)' }}
                data-testid={`access-request-${r.id}`}
              >
                <div className="min-w-0">
                  <p className="text-sm font-bold" style={{ color: 'var(--theme-text)' }}>
                    {r.engineer_name}
                    {r.engineer_company ? <span style={{ color: 'var(--theme-text-muted)', fontWeight: 400 }}> · {r.engineer_company}</span> : null}
                  </p>
                  <p className="text-[11px]" style={{ color: 'var(--theme-text-muted)' }}>
                    {t('service.eng_wants_access', 'wants access to')} <b>{r.equipment_name || t('service.eng_a_machine', 'a machine')}</b>
                    {r.message ? ` — "${r.message}"` : ''}
                  </p>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    type="button"
                    onClick={() => decideRequest(r.id, 'approve')}
                    disabled={reqBusy === r.id}
                    className="px-3 py-1.5 rounded-lg text-xs font-bold text-white disabled:opacity-50"
                    style={{ background: '#059669' }}
                    data-testid={`access-request-approve-${r.id}`}
                  >
                    {reqBusy === r.id ? '…' : t('service.eng_approve', 'Approve')}
                  </button>
                  <button
                    type="button"
                    onClick={() => decideRequest(r.id, 'decline')}
                    disabled={reqBusy === r.id}
                    className="px-3 py-1.5 rounded-lg text-xs font-bold disabled:opacity-50"
                    style={{ border: '1px solid var(--theme-border)', color: 'var(--theme-text-muted)' }}
                    data-testid={`access-request-decline-${r.id}`}
                  >
                    {t('service.eng_decline', 'Decline')}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}
      {showAdd ? (
        <section
          className="svc-card mb-3"
          style={{ padding: 16, border: '1px solid var(--theme-border)' }}
          data-testid="engineers-add-form"
        >
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
            <Field label={t('service.eng_email_existing', 'Email (existing teammate)')}>
              <input className="svc-input" data-testid="engineers-add-email"
                value={addForm.email}
                onChange={(e) => setAddForm({ ...addForm, email: e.target.value })} />
            </Field>
            <Field label={t('service.eng_full_name', 'Full name')}>
              <input className="svc-input" data-testid="engineers-add-name"
                value={addForm.full_name}
                onChange={(e) => setAddForm({ ...addForm, full_name: e.target.value })} />
            </Field>
            <Field label={t('service.eng_mobile', 'Mobile')}>
              <input className="svc-input" data-testid="engineers-add-mobile"
                value={addForm.mobile}
                onChange={(e) => setAddForm({ ...addForm, mobile: e.target.value })} />
            </Field>
            <Field label={t('service.eng_vehicle_reg', 'Vehicle reg')}>
              <input className="svc-input" data-testid="engineers-add-vehicle"
                value={addForm.vehicle_reg}
                onChange={(e) => setAddForm({ ...addForm, vehicle_reg: e.target.value })} />
            </Field>
            <Field label={t('service.eng_sage_user_id', 'Sage user ID')}>
              <input className="svc-input" data-testid="engineers-add-sage"
                value={addForm.sage_user_id}
                onChange={(e) => setAddForm({ ...addForm, sage_user_id: e.target.value })} />
            </Field>
          </div>
          <SkillPicker selected={addForm.skills} onToggle={(s) => toggleSkill(s, 'add')} />

          {/* Iter 216h87 — Trust card fields on the Add form */}
