import OrderFulfilment from './InvFulfilment';

const SOURCE_BADGE = {
  sage: { key: 'inv.orders.src_sage', label: 'Sage 200', cls: 'bg-blue-100 text-blue-700' },
  invoice: { key: 'inv.orders.src_invoice', label: 'AI Invoice', cls: 'bg-violet-100 text-violet-700' },
  crm: { key: 'inv.orders.src_crm', label: 'CRM', cls: 'bg-emerald-100 text-emerald-700' },
  manual: { key: 'inv.orders.src_manual', label: 'Manual', cls: 'bg-slate-100 text-slate-600' },
