          <input className={`${inputCls} pl-9`} placeholder={t('inv.orders.search', 'Search reference, dealer, PO…')} value={q} data-testid="inv-orders-search" onChange={(e) => setQ(e.target.value)} />
        </div>
        <select className={inputCls + ' w-auto'} value={sourceFilter} data-testid="inv-orders-source-filter" onChange={(e) => setSourceFilter(e.target.value)}>
          <option value="all">{t('inv.orders.all_sources', 'All sources')}</option>
          <option value="manual">{t('inv.orders.src_manual', 'Manual')}</option>
          <option value="invoice">{t('inv.orders.src_invoice', 'AI Invoice')}</option>
          <option value="sage">{t('inv.orders.src_sage', 'Sage 200')}</option>
          <option value="crm">{t('inv.orders.src_crm', 'CRM')}</option>
        </select>
        <select className={inputCls + ' w-auto'} value={statusFilter} data-testid="inv-orders-status-filter" onChange={(e) => setStatusFilter(e.target.value)}>
          <option value="all">{t('inv.orders.all_statuses', 'All statuses')}</option>
          <option value="needs_validation">{t('inv.orders.st_needs_validation', 'Needs validation')}</option>
          <option value="awaiting_stock">{t('inv.orders.st_awaiting_stock', 'Awaiting stock')}</option>
          <option value="partially_available">{t('inv.orders.st_partially_available', 'Partially available')}</option>
          <option value="reserved">{t('inv.orders.st_reserved', 'Reserved')}</option>
          <option value="in_transit">{t('inv.orders.st_in_transit', 'In transit')}</option>
        </select>
      </div>

      {orders === null ? <Spinner /> : shown.length === 0 ? (
        <Card className="p-10 text-center" testId="inv-orders-empty">
          <p className="text-slate-500">{t('inv.orders.empty', 'No orders yet.')}</p>
